import { ensureElement } from "../../utils/utils";
import { SETTINGS } from "../../utils/constants";
export class ContactsView {
    constructor(container, events) {
        this.events = events;
        this.eventEmitter = events;
        this.container = container;
        this.emailInput = ensureElement(SETTINGS.contacts.emailInput, this.container);
        this.submitButton = ensureElement(SETTINGS.contacts.submitButton, this.container);
        this.errors = ensureElement(SETTINGS.contacts.errors, this.container);
        this.phoneInput = ensureElement(SETTINGS.contacts.phoneInput, this.container);
    }
    setValidState(isValid, error) {
        this.submitButton.disabled = !isValid;
        this.errors.textContent = error || '';
    }
    render() {
        this.emailInput.addEventListener('input', () => {
            this.eventEmitter.emit('contacts:validate');
        });
        this.phoneInput.addEventListener('input', () => {
            this.eventEmitter.emit('contacts:validate');
        });
        this.container.addEventListener('submit', (event) => {
            event.preventDefault();
            this.eventEmitter.emit('contacts:submit', {
                email: this.emailInput.value,
                phone: this.phoneInput.value,
            });
        });
        return this.container;
    }
    resetForm() {
        this.container.reset();
    }
}
