import { ensureElement } from "../../utils/utils";
import { SETTINGS } from "../../utils/constants";
import { Component } from "../base/Component";
export class PageView extends Component {
    constructor(container, eventEmitter) {
        super(container);
        this.eventEmitter = eventEmitter;
        this.basketCounter = ensureElement(SETTINGS.basketCounter);
        this.basketButton = ensureElement(SETTINGS.basketHeader);
        this.gallery = ensureElement(SETTINGS.gallerySelector);
        this._wrapper = ensureElement(SETTINGS.pageWrapper);
        this.basketButton.addEventListener('click', () => {
            this.eventEmitter.emit('basket:open');
        });
    }
    setBasketCounter(value) {
        this.setText(this.basketCounter, String(value));
    }
    updateGallery(cards) {
        this.gallery.replaceChildren(...cards);
    }
    setlocked(value) {
        if (value) {
            this._wrapper.classList.add('page__wrapper_locked');
        }
        else {
            this._wrapper.classList.remove('page__wrapper_locked');
        }
    }
}
