import { ensureElement } from "../../utils/utils";
import { SETTINGS } from "../../utils/constants";
export class OrderView {
    constructor(container, eventEmitter) {
        this.container = container;
        this.eventEmitter = eventEmitter;
    }
    render() {
        this.paymentButtons = ensureElement(SETTINGS.order.paymentButtons, this.container);
        this.addressInput = ensureElement(SETTINGS.order.addressInput, this.container);
        this.submitButton = ensureElement(SETTINGS.order.submitButton, this.container);
        this.errors = ensureElement(SETTINGS.order.errors, this.container);
        this.onlineButton = ensureElement(SETTINGS.order.paymentButtonOnline, this.paymentButtons);
        this.cashButton = ensureElement(SETTINGS.order.paymentButtonCash, this.paymentButtons);
        return this.container;
    }
    setListeners() {
        this.paymentButtons.addEventListener('click', (event) => {
            const target = event.target;
            if (target.name === 'card' || target.name === 'cash') {
                this.eventEmitter.emit('payment:change', { method: target.name });
                this.eventEmitter.emit('order:validate');
            }
        });
        this.addressInput.addEventListener('input', () => {
            this.eventEmitter.emit('address:change', { value: this.addressInput.value });
            this.eventEmitter.emit('order:validate');
        });
        this.container.addEventListener('submit', (event) => {
            event.preventDefault();
            this.eventEmitter.emit('order:submit');
        });
    }
    setPaymentMethod(method) {
        this.onlineButton.classList.toggle(SETTINGS.order.buttonActiveClass, method === 'card');
        this.cashButton.classList.toggle(SETTINGS.order.buttonActiveClass, method === 'cash');
    }
    setAddress(value) {
        this.addressInput.value = value;
    }
    setValidState(isValid, error) {
        this.submitButton.disabled = !isValid;
        this.errors.textContent = isValid ? '' : (error || 'Заполните все поля');
    }
    resetForm() {
        this.container.reset();
        this.onlineButton.classList.remove(SETTINGS.order.buttonActiveClass);
        this.cashButton.classList.remove(SETTINGS.order.buttonActiveClass);
    }
}
